<section class="card"><div class="section-heading"><div><h2>Entradas e saídas</h2><p>Histórico de reposições e entregas de equipamentos.</p></div></div><form method="get" class="filters"><label>Tipo<select name="tipo"><option value="">Todos</option><option <?= ($_GET['tipo']??'')==='Entrada'?'selected':'' ?>>Entrada</option><option <?= ($_GET['tipo']??'')==='Saída'?'selected':'' ?>>Saída</option></select></label><button class="button secondary">Filtrar</button></form><?php if(!empty($_GET['tipo'])) $history=array_values(array_filter($history,fn($h)=>$h['tipo']===$_GET['tipo'])); require __DIR__.'/history-table.php'; ?></section>
